"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["74898"],{41253(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.conferencia_endereco_geo.municipio_nao_encontrado","status":422,"titulo":"O munic\xedpio informado n\xe3o existe no Geo"},"descricao":{"codigo":"uniplus.selecao.conferencia_endereco_geo.municipio_nao_encontrado","requisitos":["UNI-REQ-0214"],"oQueAconteceu":["No envio da inscri\xe7\xe3o, o sistema confere no Geo, o cadastro de localidades\\ndo Uni+, cada munic\xedpio que o candidato informou, como o munic\xedpio de\\nnascimento. O c\xf3digo do munic\xedpio deste campo n\xe3o consta no Geo. A recusa\\nvem no campo do munic\xedpio e, quando ele est\xe1 dentro de um grupo repet\xedvel,\\nno item daquela ocorr\xeancia.","A confer\xeancia vale s\xf3 para o campo que a inscri\xe7\xe3o pede. O munic\xedpio de um\\ncampo que ficou oculto, por exemplo a naturalidade de quem declarou\\nnacionalidade estrangeira, n\xe3o \xe9 conferido nem recusado."],"comoResolver":["Escolha o munic\xedpio de novo na lista do formul\xe1rio, que vem do Geo e \xe9\\nfiltrada pela UF informada, e envie a inscri\xe7\xe3o outra vez. Nada desta tentativa foi gravado, e o\\nmunic\xedpio escolhido na lista \xe9 aceito. O nome do\\nmunic\xedpio \xe9 sempre o que o Geo devolve no envio: n\xe3o \xe9 preciso digit\xe1-lo."],"ondeAparece":["Envio da inscri\xe7\xe3o do candidato"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Conferencia endereco geo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"38e6e984f8a69f1cdfcd140295a410206c687849"}}')}}]);